-- M6: a bigger shared exercise library with instructions.
--   exercises.instructions  short how-to cues shown in the library
-- Adds a Forearms muscle group, fills in instructions for the original seed exercises, and adds
-- more shared (user_id is null) exercises. Idempotent: an exercise that already exists by name in
-- the shared library is updated (instructions/equipment) rather than duplicated, so this is safe on
-- databases with or without supabase/seed.sql applied.
alter table exercises
  add column instructions text;

alter table exercises
  add constraint exercises_instructions_length check (instructions is null or char_length(instructions) <= 1000);

insert into muscle_groups (name) values
  ('Chest'), ('Back'), ('Shoulders'), ('Biceps'), ('Triceps'),
  ('Quads'), ('Hamstrings'), ('Glutes'), ('Calves'), ('Core'), ('Cardio'), ('Forearms')
on conflict (name) do nothing;

do $$
declare
  ex_id uuid;
  ex record;
  mg record;
  library jsonb := '[{"name": "Barbell Bench Press", "equipment": "Barbell", "muscles": ["Chest", "Triceps", "Shoulders"], "instructions": "Lie with eyes under the bar, feet flat. Grip slightly wider than shoulders, lower the bar to mid-chest with elbows about 45 degrees from the body, then press back up over the shoulders."}, {"name": "Incline Dumbbell Press", "equipment": "Dumbbell", "muscles": ["Chest", "Shoulders"], "instructions": "Set the bench to 30-45 degrees. Start with dumbbells over the upper chest, lower them to the sides of the chest, then press up and slightly in."}, {"name": "Push-Up", "equipment": "Bodyweight", "muscles": ["Chest", "Triceps"], "instructions": "Hands just wider than shoulders, body in a straight line from head to heels. Lower until the chest is near the floor, then push back up without letting the hips sag."}, {"name": "Chest Fly", "equipment": "Machine", "muscles": ["Chest"], "instructions": "Adjust the seat so handles are at chest height. With a slight bend in the elbows, bring the handles together in a wide arc, squeeze, then return under control."}, {"name": "Deadlift", "equipment": "Barbell", "muscles": ["Back", "Hamstrings", "Glutes"], "instructions": "Bar over mid-foot, hips back, shoulders over the bar, back flat. Push the floor away and stand tall with the bar close to the legs, then hinge back down."}, {"name": "Pull-Up", "equipment": "Bodyweight", "muscles": ["Back", "Biceps"], "instructions": "Hang with an overhand grip slightly wider than shoulders. Pull the chest toward the bar by driving elbows down, then lower to a full hang."}, {"name": "Lat Pulldown", "equipment": "Machine", "muscles": ["Back", "Biceps"], "instructions": "Grip the bar wider than shoulders, lean back slightly and pull it to the upper chest by driving elbows down. Let it rise under control until the arms are straight."}, {"name": "Barbell Row", "equipment": "Barbell", "muscles": ["Back", "Biceps"], "instructions": "Hinge forward to about 45 degrees with a flat back. Pull the bar to the lower ribs, squeeze the shoulder blades, then lower with control."}, {"name": "Seated Cable Row", "equipment": "Machine", "muscles": ["Back", "Biceps"], "instructions": "Sit tall with a slight knee bend. Pull the handle to the stomach while squeezing the shoulder blades together, then reach forward without rounding the back."}, {"name": "Overhead Press", "equipment": "Barbell", "muscles": ["Shoulders", "Triceps"], "instructions": "Start with the bar on the front of the shoulders, glutes and core tight. Press straight up, moving the head back then through as the bar passes the face, and lock out overhead."}, {"name": "Lateral Raise", "equipment": "Dumbbell", "muscles": ["Shoulders"], "instructions": "Stand with dumbbells at your sides and a slight elbow bend. Raise the arms out to shoulder height leading with the elbows, then lower slowly."}, {"name": "Face Pull", "equipment": "Cable", "muscles": ["Shoulders", "Back"], "instructions": "Set a rope at upper-chest height. Pull toward the face, splitting the rope and rotating the hands back so the elbows finish high and wide."}, {"name": "Barbell Curl", "equipment": "Barbell", "muscles": ["Biceps"], "instructions": "Stand with a shoulder-width underhand grip. Curl the bar up keeping the elbows at your sides, squeeze at the top, then lower fully."}, {"name": "Dumbbell Curl", "equipment": "Dumbbell", "muscles": ["Biceps"], "instructions": "Hold dumbbells with palms forward. Curl up without swinging, keeping elbows still, then lower to full extension."}, {"name": "Hammer Curl", "equipment": "Dumbbell", "muscles": ["Biceps"], "instructions": "Hold dumbbells with palms facing each other. Curl up keeping the neutral grip and elbows tucked, then lower under control."}, {"name": "Tricep Pushdown", "equipment": "Cable", "muscles": ["Triceps"], "instructions": "Stand close to a high pulley with elbows pinned to your sides. Push the handle down until the arms are straight, then let it rise to about 90 degrees."}, {"name": "Skull Crusher", "equipment": "Barbell", "muscles": ["Triceps"], "instructions": "Lie on a bench holding the bar over the chest. Bend only at the elbows to lower it toward the forehead, then extend back up."}, {"name": "Dip", "equipment": "Bodyweight", "muscles": ["Triceps", "Chest"], "instructions": "Support yourself on parallel bars with arms straight. Lower until the upper arms are about parallel to the floor, then press back up."}, {"name": "Back Squat", "equipment": "Barbell", "muscles": ["Quads", "Glutes"], "instructions": "Bar on the upper back, feet shoulder-width. Brace, sit down between the hips until thighs are at least parallel, then drive up keeping the chest up."}, {"name": "Front Squat", "equipment": "Barbell", "muscles": ["Quads", "Glutes"], "instructions": "Rest the bar on the front of the shoulders with elbows high. Squat down keeping the torso upright, then stand back up."}, {"name": "Leg Press", "equipment": "Machine", "muscles": ["Quads", "Glutes"], "instructions": "Feet shoulder-width on the platform. Lower until the knees reach about 90 degrees without the lower back lifting, then press back up without locking the knees hard."}, {"name": "Lunge", "equipment": "Dumbbell", "muscles": ["Quads", "Glutes"], "instructions": "Step forward and lower until both knees are about 90 degrees, front knee over the foot. Push through the front heel to return."}, {"name": "Leg Extension", "equipment": "Machine", "muscles": ["Quads"], "instructions": "Pad on the lower shins, knees in line with the pivot. Extend the legs until straight, pause, then lower slowly."}, {"name": "Romanian Deadlift", "equipment": "Barbell", "muscles": ["Hamstrings", "Glutes"], "instructions": "Stand holding the bar, knees soft. Push the hips back and slide the bar down the thighs until you feel a hamstring stretch, then drive the hips forward to stand."}, {"name": "Leg Curl", "equipment": "Machine", "muscles": ["Hamstrings"], "instructions": "Align the knees with the pivot. Curl the pad toward you as far as possible, squeeze, then return slowly."}, {"name": "Hip Thrust", "equipment": "Barbell", "muscles": ["Glutes"], "instructions": "Upper back on a bench, bar over the hips, feet flat. Drive the hips up until the body is level from shoulders to knees, squeeze the glutes, then lower."}, {"name": "Calf Raise", "equipment": "Machine", "muscles": ["Calves"], "instructions": "Balls of the feet on the platform, heels hanging. Rise as high as possible, pause, then lower into a full stretch."}, {"name": "Plank", "equipment": "Bodyweight", "muscles": ["Core"], "instructions": "Forearms under the shoulders, body straight from head to heels. Brace the abs and glutes and hold without letting the hips sag or pike."}, {"name": "Hanging Leg Raise", "equipment": "Bodyweight", "muscles": ["Core"], "instructions": "Hang from a bar. Raise the legs by curling the pelvis up, avoid swinging, then lower under control."}, {"name": "Cable Crunch", "equipment": "Cable", "muscles": ["Core"], "instructions": "Kneel below a high pulley holding a rope by your head. Crunch down by flexing the spine, bringing elbows toward the thighs, then return."}, {"name": "Russian Twist", "equipment": "Bodyweight", "muscles": ["Core"], "instructions": "Sit with knees bent and torso leaning back. Rotate the shoulders side to side, touching the floor beside the hips."}, {"name": "Treadmill Run", "equipment": "Machine", "muscles": ["Cardio"], "instructions": "Start at a walk to warm up, then run at a steady pace. Stay tall and land under your hips."}, {"name": "Rowing Machine", "equipment": "Machine", "muscles": ["Cardio", "Back"], "instructions": "Drive with the legs first, then lean back slightly and pull the handle to the lower ribs. Return arms, then body, then legs."}, {"name": "Cycling", "equipment": "Machine", "muscles": ["Cardio", "Quads"], "instructions": "Set the saddle so the knee is slightly bent at the bottom of the stroke. Pedal at a steady cadence with a stable upper body."}, {"name": "Dumbbell Bench Press", "equipment": "Dumbbell", "muscles": ["Chest", "Triceps", "Shoulders"], "instructions": "Lie on a flat bench with dumbbells over the chest. Lower them to the sides of the chest, then press back up until the arms are straight."}, {"name": "Incline Barbell Bench Press", "equipment": "Barbell", "muscles": ["Chest", "Shoulders", "Triceps"], "instructions": "Bench at 30-45 degrees. Lower the bar to the upper chest, then press up over the shoulders."}, {"name": "Decline Bench Press", "equipment": "Barbell", "muscles": ["Chest", "Triceps"], "instructions": "Secure the legs on a decline bench. Lower the bar to the lower chest and press back up."}, {"name": "Close-Grip Bench Press", "equipment": "Barbell", "muscles": ["Triceps", "Chest"], "instructions": "Grip the bar about shoulder-width. Lower to the lower chest with elbows tucked, then press up."}, {"name": "Machine Chest Press", "equipment": "Machine", "muscles": ["Chest", "Triceps", "Shoulders"], "instructions": "Adjust the seat so handles are at mid-chest. Press forward to near lockout, then return under control."}, {"name": "Cable Crossover", "equipment": "Cable", "muscles": ["Chest"], "instructions": "Stand between high pulleys with a slight forward lean. Bring the handles together in front of the chest in a hugging arc, then return."}, {"name": "Dumbbell Fly", "equipment": "Dumbbell", "muscles": ["Chest"], "instructions": "Lie on a bench with dumbbells over the chest and elbows slightly bent. Open the arms wide until you feel a stretch, then bring them back together."}, {"name": "Pec Deck", "equipment": "Machine", "muscles": ["Chest"], "instructions": "Sit tall with forearms or hands on the pads. Bring the pads together in front of the chest, pause, then return slowly."}, {"name": "Incline Push-Up", "equipment": "Bodyweight", "muscles": ["Chest", "Triceps"], "instructions": "Hands on a bench or box, body straight. Lower the chest to the edge and push back up."}, {"name": "Decline Push-Up", "equipment": "Bodyweight", "muscles": ["Chest", "Shoulders", "Triceps"], "instructions": "Feet on a bench, hands on the floor. Lower the chest to the floor and push back up keeping the body straight."}, {"name": "Chin-Up", "equipment": "Bodyweight", "muscles": ["Back", "Biceps"], "instructions": "Hang with an underhand shoulder-width grip. Pull until the chin clears the bar, then lower to a full hang."}, {"name": "Assisted Pull-Up", "equipment": "Machine", "muscles": ["Back", "Biceps"], "instructions": "Kneel or stand on the assist pad. Pull the chest toward the bar, then lower slowly; less assistance means more load."}, {"name": "Neutral-Grip Pulldown", "equipment": "Machine", "muscles": ["Back", "Biceps"], "instructions": "Use a close neutral-grip handle. Pull it to the upper chest driving elbows down, then let it rise under control."}, {"name": "Single-Arm Dumbbell Row", "equipment": "Dumbbell", "muscles": ["Back", "Biceps"], "instructions": "One hand and knee on a bench, back flat. Row the dumbbell to the hip, then lower to a full stretch."}, {"name": "T-Bar Row", "equipment": "Barbell", "muscles": ["Back", "Biceps"], "instructions": "Straddle the bar with a flat back and hinged hips. Pull the handle to the chest, squeeze, then lower."}, {"name": "Chest-Supported Row", "equipment": "Machine", "muscles": ["Back", "Biceps"], "instructions": "Chest against the pad. Pull the handles back squeezing the shoulder blades, then extend the arms fully."}, {"name": "Pendlay Row", "equipment": "Barbell", "muscles": ["Back"], "instructions": "Torso nearly parallel to the floor. Row the bar explosively from the floor to the lower chest, then return it to the floor each rep."}, {"name": "Straight-Arm Pulldown", "equipment": "Cable", "muscles": ["Back"], "instructions": "Face a high pulley with arms straight. Sweep the bar down to the thighs using the lats, then let it rise."}, {"name": "Rack Pull", "equipment": "Barbell", "muscles": ["Back", "Glutes", "Hamstrings"], "instructions": "Set the bar in a rack at knee height. Deadlift it to lockout with a flat back, then lower to the pins."}, {"name": "Sumo Deadlift", "equipment": "Barbell", "muscles": ["Glutes", "Quads", "Hamstrings", "Back"], "instructions": "Take a wide stance with toes out and grip inside the knees. Push the knees out, chest up, and stand the bar up close to the body."}, {"name": "Trap Bar Deadlift", "equipment": "Other", "muscles": ["Quads", "Glutes", "Hamstrings", "Back"], "instructions": "Stand inside the trap bar, grip the handles, hips back and chest up. Drive through the floor to stand tall, then lower."}, {"name": "Good Morning", "equipment": "Barbell", "muscles": ["Hamstrings", "Glutes", "Back"], "instructions": "Bar on the upper back, knees soft. Hinge at the hips with a flat back until the torso is near parallel, then stand back up."}, {"name": "Back Extension", "equipment": "Bodyweight", "muscles": ["Back", "Glutes", "Hamstrings"], "instructions": "Hips on the pad, body straight. Lower the torso by hinging at the hips, then raise back to a straight line."}, {"name": "Shrug", "equipment": "Dumbbell", "muscles": ["Back"], "instructions": "Hold dumbbells at your sides. Lift the shoulders straight up toward the ears, pause, then lower."}, {"name": "Dumbbell Shoulder Press", "equipment": "Dumbbell", "muscles": ["Shoulders", "Triceps"], "instructions": "Seated or standing, dumbbells at shoulder height. Press overhead until the arms are straight, then lower to the shoulders."}, {"name": "Arnold Press", "equipment": "Dumbbell", "muscles": ["Shoulders", "Triceps"], "instructions": "Start with palms facing you at shoulder height. Rotate the palms forward as you press overhead, then reverse on the way down."}, {"name": "Machine Shoulder Press", "equipment": "Machine", "muscles": ["Shoulders", "Triceps"], "instructions": "Handles at shoulder height. Press up to near lockout, then lower under control."}, {"name": "Push Press", "equipment": "Barbell", "muscles": ["Shoulders", "Triceps", "Quads"], "instructions": "Bar on the front of the shoulders. Dip the knees slightly, drive up with the legs and press the bar overhead."}, {"name": "Cable Lateral Raise", "equipment": "Cable", "muscles": ["Shoulders"], "instructions": "Stand side-on to a low pulley. Raise the handle out to shoulder height with a slight elbow bend, then lower slowly."}, {"name": "Front Raise", "equipment": "Dumbbell", "muscles": ["Shoulders"], "instructions": "Hold dumbbells in front of the thighs. Raise them to shoulder height with straight arms, then lower."}, {"name": "Rear Delt Fly", "equipment": "Dumbbell", "muscles": ["Shoulders", "Back"], "instructions": "Hinge forward with a flat back. Raise the dumbbells out to the sides leading with the elbows, then lower."}, {"name": "Reverse Pec Deck", "equipment": "Machine", "muscles": ["Shoulders", "Back"], "instructions": "Face the pad with arms extended. Sweep the handles back until the arms are in line with the body, then return."}, {"name": "Upright Row", "equipment": "Barbell", "muscles": ["Shoulders", "Back"], "instructions": "Hold the bar with a shoulder-width grip. Pull it up along the body to lower-chest height with elbows leading, then lower."}, {"name": "Preacher Curl", "equipment": "Barbell", "muscles": ["Biceps"], "instructions": "Upper arms on the preacher pad. Curl the bar up, then lower until the arms are nearly straight."}, {"name": "Incline Dumbbell Curl", "equipment": "Dumbbell", "muscles": ["Biceps"], "instructions": "Lie back on an incline bench with arms hanging. Curl the dumbbells up without moving the upper arms, then lower fully."}, {"name": "Cable Curl", "equipment": "Cable", "muscles": ["Biceps"], "instructions": "Face a low pulley holding the bar. Curl up keeping the elbows at your sides, then lower slowly."}, {"name": "Concentration Curl", "equipment": "Dumbbell", "muscles": ["Biceps"], "instructions": "Seated, elbow braced on the inner thigh. Curl the dumbbell to the shoulder, squeeze, then lower."}, {"name": "EZ-Bar Curl", "equipment": "Barbell", "muscles": ["Biceps"], "instructions": "Grip the angled part of the EZ bar. Curl up keeping the elbows still, then lower."}, {"name": "Overhead Tricep Extension", "equipment": "Dumbbell", "muscles": ["Triceps"], "instructions": "Hold one dumbbell overhead with both hands. Lower it behind the head by bending the elbows, then extend back up."}, {"name": "Cable Overhead Tricep Extension", "equipment": "Cable", "muscles": ["Triceps"], "instructions": "Face away from a pulley holding a rope overhead. Extend the arms forward and up, then let the rope return behind the head."}, {"name": "Tricep Kickback", "equipment": "Dumbbell", "muscles": ["Triceps"], "instructions": "Hinge forward with the upper arm parallel to the floor. Extend the elbow until the arm is straight, then return."}, {"name": "Bench Dip", "equipment": "Bodyweight", "muscles": ["Triceps"], "instructions": "Hands on a bench behind you, legs out in front. Lower by bending the elbows to about 90 degrees, then press up."}, {"name": "Diamond Push-Up", "equipment": "Bodyweight", "muscles": ["Triceps", "Chest"], "instructions": "Hands close together under the chest forming a diamond. Lower the chest to the hands and press back up."}, {"name": "Wrist Curl", "equipment": "Dumbbell", "muscles": ["Forearms"], "instructions": "Forearms on your thighs, palms up. Curl the wrists up, then lower through a full range."}, {"name": "Farmer''s Carry", "equipment": "Dumbbell", "muscles": ["Forearms", "Core", "Back"], "instructions": "Hold heavy weights at your sides, stand tall, and walk with short controlled steps."}, {"name": "Goblet Squat", "equipment": "Dumbbell", "muscles": ["Quads", "Glutes"], "instructions": "Hold a dumbbell or kettlebell at the chest. Squat down between the knees keeping the chest up, then stand."}, {"name": "Hack Squat", "equipment": "Machine", "muscles": ["Quads", "Glutes"], "instructions": "Back against the pad, feet shoulder-width. Lower until the thighs are about parallel, then press back up."}, {"name": "Bulgarian Split Squat", "equipment": "Dumbbell", "muscles": ["Quads", "Glutes"], "instructions": "Rear foot on a bench behind you. Lower until the front thigh is near parallel, then drive up through the front foot."}, {"name": "Walking Lunge", "equipment": "Dumbbell", "muscles": ["Quads", "Glutes"], "instructions": "Step forward into a lunge, then bring the back foot through into the next step, alternating legs."}, {"name": "Reverse Lunge", "equipment": "Dumbbell", "muscles": ["Quads", "Glutes"], "instructions": "Step back and lower until both knees are about 90 degrees, then return to standing."}, {"name": "Step-Up", "equipment": "Dumbbell", "muscles": ["Quads", "Glutes"], "instructions": "Place one foot on a box. Drive through that foot to stand on the box, then step down under control."}, {"name": "Box Squat", "equipment": "Barbell", "muscles": ["Quads", "Glutes", "Hamstrings"], "instructions": "Squat back until you sit lightly on a box, pause, then drive up."}, {"name": "Smith Machine Squat", "equipment": "Machine", "muscles": ["Quads", "Glutes"], "instructions": "Bar on the upper back, feet slightly forward. Squat to parallel or below, then press up."}, {"name": "Sissy Squat", "equipment": "Bodyweight", "muscles": ["Quads"], "instructions": "Hold support, rise onto the toes and lean back as the knees travel forward. Lower, then return to standing."}, {"name": "Nordic Hamstring Curl", "equipment": "Bodyweight", "muscles": ["Hamstrings"], "instructions": "Kneel with ankles anchored. Lower the body forward as slowly as possible, catch yourself, and push back up."}, {"name": "Seated Leg Curl", "equipment": "Machine", "muscles": ["Hamstrings"], "instructions": "Pad above the ankles, thigh pad snug. Curl the legs down and back, then return slowly."}, {"name": "Single-Leg Romanian Deadlift", "equipment": "Dumbbell", "muscles": ["Hamstrings", "Glutes"], "instructions": "Stand on one leg holding a dumbbell. Hinge forward with the free leg extending back, then return to standing."}, {"name": "Glute Bridge", "equipment": "Bodyweight", "muscles": ["Glutes", "Hamstrings"], "instructions": "Lie on your back, knees bent. Drive the hips up until the body is straight from shoulders to knees, then lower."}, {"name": "Cable Pull-Through", "equipment": "Cable", "muscles": ["Glutes", "Hamstrings"], "instructions": "Face away from a low pulley with the rope between your legs. Hinge back, then drive the hips forward to stand tall."}, {"name": "Hip Abduction", "equipment": "Machine", "muscles": ["Glutes"], "instructions": "Sit with pads on the outside of the knees. Push the legs apart, pause, then return slowly."}, {"name": "Hip Adduction", "equipment": "Machine", "muscles": ["Quads"], "instructions": "Sit with pads on the inside of the knees. Squeeze the legs together, then return slowly."}, {"name": "Cable Kickback", "equipment": "Cable", "muscles": ["Glutes"], "instructions": "Ankle strap on a low pulley. Kick the leg straight back squeezing the glute, then return."}, {"name": "Seated Calf Raise", "equipment": "Machine", "muscles": ["Calves"], "instructions": "Pads on the lower thighs, balls of the feet on the platform. Raise the heels as high as possible, then lower into a stretch."}, {"name": "Standing Calf Raise", "equipment": "Bodyweight", "muscles": ["Calves"], "instructions": "Stand on a step with heels hanging. Rise onto the toes, pause, then lower below the step."}, {"name": "Ab Wheel Rollout", "equipment": "Other", "muscles": ["Core"], "instructions": "Kneel holding the wheel. Roll forward keeping the core braced and back flat, then pull back to the start."}, {"name": "Crunch", "equipment": "Bodyweight", "muscles": ["Core"], "instructions": "Lie on your back with knees bent. Curl the shoulders off the floor by contracting the abs, then lower."}, {"name": "Bicycle Crunch", "equipment": "Bodyweight", "muscles": ["Core"], "instructions": "Lie on your back, hands by your head. Bring opposite elbow and knee together, alternating sides."}, {"name": "Side Plank", "equipment": "Bodyweight", "muscles": ["Core"], "instructions": "Lie on your side propped on one forearm. Lift the hips so the body is straight and hold."}, {"name": "Dead Bug", "equipment": "Bodyweight", "muscles": ["Core"], "instructions": "Lie on your back, arms up and knees at 90 degrees. Lower the opposite arm and leg while keeping the lower back down, then switch."}, {"name": "Pallof Press", "equipment": "Cable", "muscles": ["Core"], "instructions": "Stand side-on to a chest-height pulley. Press the handle straight out and resist the rotation, then bring it back."}, {"name": "Mountain Climber", "equipment": "Bodyweight", "muscles": ["Core", "Cardio"], "instructions": "Start in a push-up position. Drive the knees toward the chest one at a time at a quick pace."}, {"name": "Hanging Knee Raise", "equipment": "Bodyweight", "muscles": ["Core"], "instructions": "Hang from a bar. Raise the knees toward the chest without swinging, then lower."}, {"name": "Kettlebell Swing", "equipment": "Kettlebell", "muscles": ["Glutes", "Hamstrings", "Core"], "instructions": "Hinge and hike the kettlebell back between the legs, then snap the hips forward to swing it to chest height."}, {"name": "Kettlebell Goblet Squat", "equipment": "Kettlebell", "muscles": ["Quads", "Glutes"], "instructions": "Hold the kettlebell by the horns at the chest. Squat down with an upright torso, then stand."}, {"name": "Turkish Get-Up", "equipment": "Kettlebell", "muscles": ["Core", "Shoulders"], "instructions": "Lying down with the kettlebell pressed up, stand up in steps while keeping the arm locked overhead, then reverse."}, {"name": "Kettlebell Clean and Press", "equipment": "Kettlebell", "muscles": ["Shoulders", "Glutes", "Core"], "instructions": "Clean the kettlebell to the rack position, then press it overhead. Lower to the rack and back down."}, {"name": "Band Pull-Apart", "equipment": "Band", "muscles": ["Shoulders", "Back"], "instructions": "Hold a band at shoulder height with straight arms. Pull it apart until it touches the chest, then return."}, {"name": "Banded Face Pull", "equipment": "Band", "muscles": ["Shoulders", "Back"], "instructions": "Anchor a band at head height. Pull toward the face with elbows high, then return."}, {"name": "Band Lateral Walk", "equipment": "Band", "muscles": ["Glutes"], "instructions": "Band around the legs above the knees. Stay in a half squat and step sideways, keeping tension on the band."}, {"name": "Burpee", "equipment": "Bodyweight", "muscles": ["Cardio", "Chest", "Quads"], "instructions": "Squat down, jump the feet back to a plank, return the feet, and jump up."}, {"name": "Jump Rope", "equipment": "Other", "muscles": ["Cardio", "Calves"], "instructions": "Stay on the balls of the feet and turn the rope with the wrists, keeping jumps small."}, {"name": "Stair Climber", "equipment": "Machine", "muscles": ["Cardio", "Glutes", "Quads"], "instructions": "Stand tall without leaning on the rails and step at a steady pace."}, {"name": "Elliptical", "equipment": "Machine", "muscles": ["Cardio"], "instructions": "Stand tall, push and pull the handles, and move at a steady cadence."}, {"name": "Assault Bike", "equipment": "Machine", "muscles": ["Cardio"], "instructions": "Push and pull the handles while pedaling; go steady for endurance or all-out for intervals."}, {"name": "Box Jump", "equipment": "Bodyweight", "muscles": ["Quads", "Glutes", "Cardio"], "instructions": "Stand in front of a box, swing the arms and jump onto it landing softly, then step down."}, {"name": "Sled Push", "equipment": "Other", "muscles": ["Quads", "Glutes", "Cardio"], "instructions": "Lean into the sled with arms extended and drive it forward with short powerful steps."}, {"name": "Power Clean", "equipment": "Barbell", "muscles": ["Back", "Glutes", "Quads", "Shoulders"], "instructions": "Pull the bar from the floor, extend the hips explosively and pull under to catch it on the front of the shoulders."}, {"name": "Landmine Press", "equipment": "Barbell", "muscles": ["Shoulders", "Chest"], "instructions": "Hold the end of a landmine bar at the shoulder. Press it up and forward until the arm is straight, then lower."}, {"name": "Inverted Row", "equipment": "Bodyweight", "muscles": ["Back", "Biceps"], "instructions": "Lie under a bar set at waist height. Pull the chest to the bar keeping the body straight, then lower."}]';
begin
  for ex in select * from jsonb_array_elements(library)
  loop
    select id into ex_id from exercises
      where user_id is null and lower(name) = lower(ex.value->>'name')
      limit 1;

    if ex_id is null then
      insert into exercises (user_id, name, equipment, instructions)
      values (null, ex.value->>'name', ex.value->>'equipment', ex.value->>'instructions')
      returning id into ex_id;
    else
      update exercises
        set instructions = ex.value->>'instructions',
            equipment = coalesce(equipment, ex.value->>'equipment')
        where id = ex_id;
    end if;

    for mg in select * from jsonb_array_elements_text(ex.value->'muscles')
    loop
      insert into exercise_muscle_groups (exercise_id, muscle_group_id)
      select ex_id, id from muscle_groups where name = mg.value
      on conflict do nothing;
    end loop;
  end loop;
end $$;
